type Vhosts = NonNullable<
  NonNullable<Parameters<typeof createTopologyFakeDeps>[0]>['vhosts']
>;

async function answer(
  vhosts: Vhosts,
  input: { vhost?: string; queue: string } = { queue: 'q' },
  options: Parameters<typeof createTopologyFakeDeps>[0] = {},
) {
  const engine = createTestExecutor();
  engine.executor.register(
    createQueuesEffectiveConfigAction(
      createTopologyFakeDeps({ ...options, vhosts }),
    ),
  );
  const outcome = await engine.executor.run(
    def,
    { cid: 'c1', vhost: '/', ...input },
    createTestContext({ idempotencyKey: KEY }),
  );
  if (outcome.kind !== 'output') throw new Error(`got ${outcome.kind}`);
  return outcome.output;
}

describe('M1-20 AC-5 effective config returns provenance per key', () => {
  const vhosts = {
    '/': {
      queues: [
        {
          name: 'q',
          type: 'quorum',
          arguments: {
            'x-max-length': 100,
            'x-dead-letter-exchange': 'arg-dlx',
          },
          policy: 'p',
          operator_policy: 'o',
          delivery_limit: 20,
        },
      ],
      policies: [
        {
          name: 'p',
          pattern: '.*',
          definition: { 'max-length': 50, 'dead-letter-exchange': 'user-dlx' },
        },
      ],
      operatorPolicies: [
        { name: 'o', pattern: '.*', definition: { 'max-length': 80 } },
      ],
    },
  };

  it('resolves max-length across the argument, the user policy and the operator policy', async () => {
    const out = await answer(vhosts);

    expect(out.queueType).toBe('quorum');
    expect(out.version).toBe('4.3.6');
    expect(out.layers.user).toEqual({ state: 'policy', name: 'p' });
    expect(out.layers.operator).toEqual({ state: 'policy', name: 'o' });
    const entry = out.effective?.entries['max-length'];
    expect(entry).toMatchObject({
      key: 'max-length',
      argument: 'x-max-length',
      status: 'effective',
      value: 50,
    });
    expect(entry?.rule).toContain('min');
    // Every input is listed with the layer it came from, and one of them decided.
    expect(entry?.provenance.map((p) => [p.layer, p.name, p.value])).toEqual(
      expect.arrayContaining([
        ['argument', 'x-max-length', 100],
        ['user-policy', 'p', 50],
        ['operator-policy', 'o', 80],
      ]),
    );
    expect(entry?.provenance.some((p) => p.role === 'deciding')).toBe(true);
    // What the broker calls the effective policy is the merged one, and the answer says it is not.
    expect(out.effective?.mergedPolicy.notEffective).toBe(true);
    expect(out.effective?.mergedPolicy.entries['max-length']).toMatchObject({
      status: 'value',
      value: 50,
    });
  });

  it('gives every key it reports a provenance list, and the argument beats the policy for the dead-letter exchange', async () => {
    const out = await answer(vhosts);

    const entries = Object.values(out.effective?.entries ?? {});
    expect(entries.length).toBeGreaterThan(3);
    for (const entry of entries) {
      expect(Array.isArray(entry.provenance)).toBe(true);
    }
    expect(out.effective?.entries['dead-letter-exchange']).toMatchObject({
      status: 'effective',
      value: 'arg-dlx',
    });
    expect(out.gaps).toEqual([]);
  });

  it('answers null, with the layer and the gap, when a policy cannot be read', async () => {
    const out = await answer({
      '/': { ...vhosts['/'], policies: 'forbidden' },
    });

    expect(out.effective).toBeNull();
    expect(out.layers.user).toEqual({ state: 'unknown', why: 'unreadable' });
    expect(out.gaps).toContain('policy-unreadable');
  });

  it('reports a mixed-version cluster and an unreadable version', async () => {
    const out = await answer(
      vhosts,
      { queue: 'q' },
      {
        profile: {
          versions: {
            min: null,
            perNode: {},
            mixed: true,
            build: 'oss',
          },
        },
      },
    );

    expect(out.mixedVersions).toBe(true);
    expect(out.version).toBeNull();
    // Without a version the registry cannot say which rule applies: unknown, never a default.
    expect(out.effective?.entries['max-length']?.status).toBe('unknown');
  });
});
